"""tessaro-feeds: Vendor feed certificate management."""

import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 hex fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """A pin store that maps hosts to their expected certificate fingerprints."""

    def __init__(self):
        self._pins = {}

    @classmethod
    def load(cls):
        """Load the default pin store."""
